use verus::prelude::*;

verus! {

    // Copy the contents of `a` into a new vector `b`.
    // We assume `a.len() <= 100`.
    // Postcondition: `b.len() == a.len()` and for all valid indices i,
    // `b[i] == a[i]`.
    fn copy(a: &Vec<u64>) -> Vec<u64> {
        // Precondition: input length at most 100
        requires a.len() <= 100;

        // Postcondition: the result `b` has the same length as `a`
        // and every element is equal.
        ensures |b: Vec<u64>|
            b.len() == a.len()
            &&
            forall(|i: usize| i < a.len() ==> *b.index(i) == *a.index(i));

        // Allocate a new vector with sufficient capacity
        let mut b = Vec::with_capacity(a.len());

        // We'll copy element-by-element
        let mut i: usize = 0;
        while i < a.len() {
            // Loop invariants to ensure correctness
            invariant i <= a.len();
            invariant b.len() == i;
            invariant forall(|j: usize| j < i ==> *b.index(j) == *a.index(j));
            decreases a.len() - i;

            // Copy the i-th element
            let x: u64 = *a.index(i);
            b.push(x);

            i = i + 1;
        }

        // Return the fully populated copy
        b
    }
}